1	import vm from 'node:vm';
2	import fs from 'node:fs';
3	import assert from 'node:assert/strict';
4	const root = '/root/bench-runs/h4-610ab0b5/public/';
5	const src = fs.readFileSync(root + 'app.js', 'utf8');
6	const html = fs.readFileSync(root + 'index.html', 'utf8');
7	for (const bad of ['http://', 'https://', 'innerHTML', 'querySelector', 'createTextNode', 'setAttribute', 'classList', 'console', 'res.ok', '.text()', 'import', 'export', 'encodeURIComponent', 'URLSearchParams'])
8	  assert(!src.includes(bad), 'app.js has ' + bad);
9	for (const bad of ['http://', 'https://', '<option', 'Aurora', 'Borealis', 'Cosmos'])
10	  assert(!html.includes(bad), 'html has ' + bad);
11	assert(!/\son\w+\s*=/.test(html), 'on* attr');
12	assert(/<script src="\/app.js"><\/script>\s*<\/body>/.test(html));
13	assert.equal((html.match(/<h1/g) || []).length, 1);
14	assert.equal((html.match(/<script/g) || []).length, 1);
15	
16	class El {
17	  constructor(tag) { this.tag = tag; this.children = []; this.listeners = {}; this.value = ''; this.disabled = false; this.type = ''; }
18	  get textContent() { return this.children.map(c => typeof c === 'string' ? c : c.textContent).join(''); }
19	  set textContent(v) { this.children = v === '' ? [] : [String(v)]; }
20	  append(...n) { this.children.push(...n); }
21	  replaceChildren(...n) { this.children = [...n]; }
22	  addEventListener(t, f) { (this.listeners[t] ||= []).push(f); }
23	  fire(t) { const ev = { prevented: false, preventDefault() { ev.prevented = true; } }; for (const f of this.listeners[t] || []) f(ev); return ev; }
24	}
25	function setup(fetchImpl) {
26	  const els = {};
27	  for (const id of ['booking-form', 'room', 'title', 'date', 'start', 'end', 'book', 'filter-date', 'show-all', 'booking-list', 'error']) els[id] = new El(id);
28	  const calls = [];
29	  const ctx = { document: { getElementById: id => els[id], createElement: t => new El(t) }, fetch: (u, o) => { calls.push([u, o]); return fetchImpl(u, o, calls.length); } };
30	  vm.runInNewContext(src, ctx);
31	  return { els, calls };
32	}
33	const tick = () => new Promise(r => setTimeout(r, 5));
34	const reply = (status, body, bad) => ({ status, json: () => bad ? Promise.reject(new Error('x')) : Promise.resolve(body) });
35	const defer = () => { let r; const p = new Promise(x => { r = x; }); return { p, r }; };
36	const never = () => new Promise(() => {});
37	
38	// load
39	let bookings = [{ id: 1, room: 'Aurora', title: '<b>x</b>', date: '2026-11-03', start: '09:00', end: '10:00' }];
40	let s = setup(u => Promise.resolve(u === '/api/rooms' ? reply(200, { rooms: ['Aurora', 'Borealis', 'Cosmos'] }) : reply(200, { bookings })));
41	assert.deepEqual(s.calls.map(c => c[0]), ['/api/rooms', '/api/bookings']);
42	await tick();
43	assert.deepEqual(s.els.room.children.map(o => [o.tag, o.value, o.textContent]), [['option', 'Aurora', 'Aurora'], ['option', 'Borealis', 'Borealis'], ['option', 'Cosmos', 'Cosmos']]);
44	const li = s.els['booking-list'].children[0];
45	assert.equal(li.tag, 'li');
46	assert.equal(li.children.length, 2);
47	assert.equal(li.children[0], '2026-11-03 09:00-10:00 Aurora: <b>x</b>');
48	assert.equal(li.children[1].type, 'button');
49	assert.equal(li.children[1].textContent, 'Cancel');
50	// filter
51	s.els['filter-date'].value = '2026-11-03';
52	s.els['filter-date'].fire('input');
53	assert.equal(s.calls.length, 2);
54	s.els['filter-date'].fire('change');
55	assert.equal(s.calls.at(-1)[0], '/api/bookings?date=2026-11-03');
56	s.els['show-all'].fire('click');
57	assert.equal(s.els['filter-date'].value, '');
58	assert.equal(s.calls.at(-1)[0], '/api/bookings');
59	assert.equal(s.calls.length, 4);
60	bookings = [];
61	s.els['filter-date'].fire('change');
62	await tick();
63	assert.equal(s.els['booking-list'].children.length, 1);
64	assert.deepEqual(s.els['booking-list'].children[0].children, ['No bookings.']);
65	
66	// rooms error / no reply / json reject
67	s = setup(u => u === '/api/rooms' ? Promise.resolve(reply(500, { error: 'internal error' })) : never());
68	await tick();
69	assert.equal(s.els.error.textContent, 'internal error');
70	assert.equal(s.els.room.children.length, 0);
71	s = setup(u => u === '/api/rooms' ? Promise.resolve(reply(500, [1])) : never());
72	await tick();
73	assert.equal(s.els.error.textContent, 'Request failed.');
74	s = setup(u => u === '/api/rooms' ? Promise.resolve(reply(200, null, true)) : never());
75	await tick();
76	assert.equal(s.els.error.textContent, 'Could not reach the server.');
77	s = setup(u => u === '/api/rooms' ? Promise.reject(new TypeError('x')) : never());
78	await tick();
79	assert.equal(s.els.error.textContent, 'Could not reach the server.');
80	
81	// list errors keep list
82	s = setup((u, o, n) => u === '/api/rooms' ? never() : n === 2 ? Promise.resolve(reply(200, { bookings: [] })) : Promise.resolve(reply(400, { error: 'date must be a valid YYYY-MM-DD date' })));
83	await tick();
84	s.els['filter-date'].fire('change');
85	await tick();
86	assert.equal(s.els.error.textContent, 'date must be a valid YYYY-MM-DD date');
87	assert.deepEqual(s.els['booking-list'].children[0].children, ['No bookings.']);
88	
89	// stale list fetch
90	const d1 = defer(), d2 = defer();
91	s = setup((u, o, n) => u === '/api/rooms' ? never() : (n === 2 ? d1.p : d2.p));
92	s.els['filter-date'].fire('change');
93	d2.r(reply(200, { bookings: [] }));
94	await tick();
95	d1.r(reply(400, { error: 'stale' }));
96	await tick();
97	assert.equal(s.els.error.textContent, '');
98	assert.deepEqual(s.els['booking-list'].children[0].children, ['No bookings.']);
99	
100	// booking
101	let postReply = defer();
102	s = setup((u, o) => u === '/api/bookings' && o.method === 'POST' ? postReply.p : u === '/api/rooms' ? Promise.resolve(reply(200, { rooms: ['Aurora'] })) : Promise.resolve(reply(200, { bookings: [] })));
103	await tick();
104	s.els.title.value = ' T ';
105	s.els.date.value = '2026-11-03';
106	s.els.start.value = '09:00';
107	s.els.end.value = '10:00';
108	s.els.room.value = 'Aurora';
109	s.els.error.textContent = 'old';
110	let ev = s.els['booking-form'].fire('submit');
111	assert(ev.prevented);
112	assert.equal(s.els.book.disabled, true);
113	const [u, o] = s.calls.at(-1);
114	assert.equal(u, '/api/bookings');
115	assert.equal(o.method, 'POST');
116	assert.equal(JSON.stringify(o.headers), JSON.stringify({ 'Content-Type': 'application/json' }));
117	assert.deepEqual(JSON.parse(o.body), { room: 'Aurora', title: ' T ', date: '2026-11-03', start: '09:00', end: '10:00' });
118	const n = s.calls.length;
119	ev = s.els['booking-form'].fire('submit');
120	assert(ev.prevented);
121	assert.equal(s.calls.length, n);
122	postReply.r(reply(201, { id: 1 }));
123	await tick();
124	assert.equal(s.els.book.disabled, false);
125	assert.equal(s.els.title.value, '');
126	assert.equal(s.els.date.value, '2026-11-03');
127	assert.equal(s.els.error.textContent, '');
128	assert.equal(s.calls.at(-1)[0], '/api/bookings');
129	assert.equal(s.calls.length, n + 1);
130	postReply = defer();
131	s.els.title.value = 'X';
132	s.els['booking-form'].fire('submit');
133	postReply.r(reply(409, { error: 'room is already booked from 09:00 to 10:00' }));
134	await tick();
135	assert.equal(s.els.error.textContent, 'room is already booked from 09:00 to 10:00');
136	assert.equal(s.els.title.value, 'X');
137	assert.equal(s.calls.length, n + 2);
138	postReply = defer();
139	s.els['booking-form'].fire('submit');
140	postReply.r(reply(201, null, true));
141	await tick();
142	assert.equal(s.els.error.textContent, 'Could not reach the server.');
143	assert.equal(s.els.book.disabled, false);
144	assert.equal(s.els.title.value, 'X');
145	assert.equal(s.calls.length, n + 3);
146	
147	// cancel
148	let del = defer();
149	let readBody = false;
150	s = setup((u, o) => o.method === 'DELETE' ? del.p : u === '/api/rooms' ? Promise.resolve(reply(200, { rooms: [] })) : Promise.resolve(reply(200, { bookings: [{ id: 7, room: 'Cosmos', title: 't', date: '2026-01-01', start: '01:00', end: '02:00' }] })));
151	await tick();
152	let btn = s.els['booking-list'].children[0].children[1];
153	btn.fire('click');
154	assert.equal(btn.disabled, true);
155	assert.equal(s.calls.at(-1)[0], '/api/bookings/7');
156	assert.equal(s.calls.at(-1)[1].method, 'DELETE');
157	s.els.error.textContent = 'old';
158	del.r({ status: 204, json() { readBody = true; return Promise.reject(new Error()); } });
159	await tick();
160	assert(!readBody);
161	assert.equal(btn.disabled, false);
162	assert.equal(s.els.error.textContent, '');
163	assert.equal(s.calls.at(-1)[0], '/api/bookings');
164	const m = s.calls.length;
165	btn = s.els['booking-list'].children[0].children[1];
166	del = defer();
167	btn.fire('click');
168	del.r(reply(404, { error: 'booking not found' }));
169	await tick();
170	assert.equal(s.els.error.textContent, 'booking not found');
171	assert.equal(s.calls.length, m + 2);
172	btn = s.els['booking-list'].children[0].children[1];
173	del = defer();
174	btn.fire('click');
175	del.r(Promise.reject(new TypeError()));
176	await tick();
177	assert.equal(s.els.error.textContent, 'Could not reach the server.');
178	assert.equal(s.calls.length, m + 3);
179	assert.equal(btn.disabled, false);
180	process.stdout.write('ALL OK\n');
