import { test } from 'node:test';
import assert from 'node:assert/strict';
import vm from 'node:vm';
import { loadPage, reply, flush, okScript, booking, ROOMS } from './support/fake-dom.mjs';

const NO_REPLY = 'Could not reach the server.';
const FAILED = 'Request failed.';
const URL_RE = /^\/api\/(rooms|bookings(\?date=.*|\/\d+)?)$/;

// Rooms answer at once, every other request stays pending until the test settles it.
const roomsOnly = (call) => (call.url === '/api/rooms' ? reply(200, { rooms: ROOMS }) : undefined);

async function boot(script = okScript()) {
  const h = loadPage(script);
  h.run();
  await flush();
  return h;
}

// Every test ends here: no API outside the allow-list was touched, only path-only URLs used.
function done(h) {
  assert.deepEqual(h.violations, []);
  for (const url of h.urls()) assert.match(url, URL_RE);
}

const rowTexts = (h) => h.els['booking-list'].children.map(
  (li) => li.children.map((c) => (c.nodeType === 3 ? c.data : c.tagName)),
);
const listText = (h) => h.els['booking-list'].children.map((li) => li.children[0].data);
const method = (call) => (call.options ? call.options.method : 'GET');
const fill = (h, over = {}) => {
  const v = { room: 'Borealis', title: 'Retro', date: '2026-11-03', start: '09:00', end: '10:00', ...over };
  for (const [id, value] of Object.entries(v)) h.els[id].value = value;
  return v;
};
const submit = (h) => h.dispatch(h.els['booking-form'], 'submit');
const lastCall = (h) => h.calls[h.calls.length - 1];

test('load: two synchronous fetches, rooms then bookings, GET, no wait for rooms', () => {
  const h = loadPage(roomsOnly);
  assert.equal(h.calls.length, 0);
  h.run();
  assert.deepEqual(h.urls(), ['/api/rooms', '/api/bookings']);
  for (const call of h.calls) assert.equal(method(call), 'GET');
  done(h);
});

test('page script sees only document and fetch', async () => {
  const h = await boot();
  for (const name of ['window', 'XMLHttpRequest', 'setTimeout', 'console', 'localStorage']) {
    assert.equal(vm.runInContext(`typeof ${name}`, h.context), 'undefined', name);
  }
  done(h);
});

test('rooms success fills three options in order', async () => {
  const h = await boot();
  const kids = h.els.room.children;
  assert.equal(kids.length, 3);
  assert.deepEqual(kids.map((o) => o.tagName), ['option', 'option', 'option']);
  assert.deepEqual(kids.map((o) => o.value), ROOMS);
  assert.deepEqual(kids.map((o) => o.textContent), ROOMS);
  assert.equal(h.els.room.value, 'Aurora');
  done(h);
});

test('rooms error replies show the message and leave the select empty', async () => {
  const cases = [
    [500, { error: 'boom' }, 'boom'],
    [500, { error: 5 }, FAILED],
    [500, [], FAILED],
    [500, 'x', FAILED],
    [500, null, FAILED],
    [500, {}, FAILED],
    [201, { rooms: ROOMS }, FAILED],
  ];
  for (const [status, body, message] of cases) {
    const h = await boot((call) => (call.url === '/api/rooms' ? reply(status, body) : undefined));
    assert.equal(h.els.error.textContent, message, JSON.stringify(body));
    assert.equal(h.els.room.children.length, 0);
    done(h);
  }
});

test('rooms: fetch rejection and unreadable body mean no reply', async () => {
  const rejected = await boot((call) => (call.url === '/api/rooms' ? 'reject' : undefined));
  assert.equal(rejected.els.error.textContent, NO_REPLY);
  assert.equal(rejected.els.room.children.length, 0);
  const badBody = await boot((call) => (call.url === '/api/rooms' ? reply(200, null, { badJson: true }) : undefined));
  assert.equal(badBody.els.error.textContent, NO_REPLY);
  assert.equal(badBody.els.room.children.length, 0);
  done(rejected);
  done(badBody);
});

test('list renders one li per booking in reply order with text and Cancel button', async () => {
  const b1 = booking(1, { date: '2026-12-01', title: 'Later' });
  const b2 = booking(2);
  const h = await boot(okScript([b1, b2]));
  assert.deepEqual(listText(h), [
    '2026-12-01 09:00-10:00 Aurora: Later',
    '2026-11-03 09:00-10:00 Aurora: Standup',
  ]);
  for (const li of h.els['booking-list'].children) {
    assert.equal(li.tagName, 'li');
    assert.equal(li.children.length, 2);
    assert.equal(li.children[0].nodeType, 3);
    assert.equal(li.children[1].tagName, 'button');
    assert.equal(li.children[1].type, 'button');
    assert.equal(li.children[1].textContent, 'Cancel');
  }
  done(h);
});

test('list: empty reply shows a single No bookings. item', async () => {
  const h = await boot(okScript([]));
  assert.equal(h.els['booking-list'].children.length, 1);
  assert.deepEqual(rowTexts(h), [['No bookings.']]);
  done(h);
});

test('list: HTML in a title stays plain text', async () => {
  const h = await boot(okScript([booking(1, { title: '<b>x</b>' })]));
  assert.equal(listText(h)[0], '2026-11-03 09:00-10:00 Aurora: <b>x</b>');
  done(h);
});

test('list: a new render replaces the previous content', async () => {
  const h = await boot(okScript([booking(1), booking(2), booking(3)]));
  assert.equal(h.els['booking-list'].children.length, 3);
  h.dispatch(h.els['filter-date'], 'change');
  await flush();
  assert.equal(h.els['booking-list'].children.length, 3);
  const h2 = await boot(roomsOnly);
  h2.respond(1, reply(200, { bookings: [booking(1), booking(2)] }));
  await flush();
  h2.dispatch(h2.els['filter-date'], 'change');
  h2.respond(2, reply(200, { bookings: [booking(9)] }));
  await flush();
  assert.equal(h2.els['booking-list'].children.length, 1);
  done(h);
  done(h2);
});

test('list: error status shows message and keeps the list', async () => {
  const h = await boot(okScript([booking(1)]));
  const before = listText(h);
  h.dispatch(h.els['filter-date'], 'change');
  h.respond(2, reply(400, { error: 'date must be a valid YYYY-MM-DD date' }));
  await flush();
  assert.equal(h.els.error.textContent, 'date must be a valid YYYY-MM-DD date');
  assert.deepEqual(listText(h), before);
  done(h);
});

test('list: a non-200 success-like status is an error', async () => {
  const h = await boot(okScript([booking(1)]));
  const before = listText(h);
  h.dispatch(h.els['filter-date'], 'change');
  h.respond(2, reply(201, { bookings: [] }));
  await flush();
  assert.equal(h.els.error.textContent, FAILED);
  assert.deepEqual(listText(h), before);
  h.dispatch(h.els['filter-date'], 'change');
  h.respond(3, reply(204, { error: 'from body' }));
  await flush();
  assert.equal(h.els.error.textContent, 'from body');
  done(h);
});

test('list: no reply shows the network message and keeps the list', async () => {
  const h = await boot(okScript([booking(1)]));
  const before = listText(h);
  h.dispatch(h.els['filter-date'], 'change');
  h.fail(2);
  await flush();
  assert.equal(h.els.error.textContent, NO_REPLY);
  assert.deepEqual(listText(h), before);
  h.dispatch(h.els['filter-date'], 'change');
  h.respond(3, reply(200, null, { badJson: true }));
  await flush();
  assert.equal(h.els.error.textContent, NO_REPLY);
  assert.deepEqual(listText(h), before);
  done(h);
});

test('list: success leaves #error alone', async () => {
  const h = await boot(okScript([booking(1)]));
  h.els.error.textContent = 'keep';
  h.dispatch(h.els['filter-date'], 'change');
  await flush();
  assert.equal(h.els.error.textContent, 'keep');
  done(h);
});

const OUTCOMES = {
  success: (h, i) => h.respond(i, reply(200, { bookings: [booking(i, { title: `T${i}` })] })),
  errorStatus: (h, i) => h.respond(i, reply(500, { error: `late ${i}` })),
  rejection: (h, i) => h.fail(i),
};

test('stale lists: the later fetch wins when the earlier one settles after it', async () => {
  for (const [name, settleA] of Object.entries(OUTCOMES)) {
    const h = await boot(roomsOnly);
    h.dispatch(h.els['filter-date'], 'change');
    h.els.error.textContent = 'keep';
    h.respond(2, reply(200, { bookings: [booking(2, { title: 'B' })] }));
    await flush();
    settleA(h, 1);
    await flush();
    assert.deepEqual(listText(h), ['2026-11-03 09:00-10:00 Aurora: B'], name);
    assert.equal(h.els.error.textContent, 'keep', name);
    done(h);
  }
});

test('stale lists: the earlier outcome is ignored even when it arrives first', async () => {
  for (const [name, settleA] of Object.entries(OUTCOMES)) {
    const h = await boot(roomsOnly);
    h.dispatch(h.els['filter-date'], 'change');
    h.els.error.textContent = 'keep';
    settleA(h, 1);
    await flush();
    assert.equal(h.els['booking-list'].children.length, 0, name);
    assert.equal(h.els.error.textContent, 'keep', name);
    OUTCOMES.success(h, 2);
    await flush();
    assert.deepEqual(listText(h), ['2026-11-03 09:00-10:00 Aurora: T2'], name);
    done(h);
  }
});

test('filter: change fetches synchronously with the value unchanged', async () => {
  const h = await boot();
  const n = h.calls.length;
  h.els['filter-date'].value = '2026-11-03';
  h.dispatch(h.els['filter-date'], 'change');
  assert.equal(h.calls.length, n + 1);
  assert.equal(lastCall(h).url, '/api/bookings?date=2026-11-03');
  assert.equal(method(lastCall(h)), 'GET');
  h.els['filter-date'].value = 'a b&c';
  h.dispatch(h.els['filter-date'], 'change');
  assert.equal(lastCall(h).url, '/api/bookings?date=a b&c');
  h.els['filter-date'].value = '';
  h.dispatch(h.els['filter-date'], 'change');
  assert.equal(lastCall(h).url, '/api/bookings');
  assert.equal(h.calls.length, n + 3);
  done(h);
});

test('filter: input event does nothing', async () => {
  const h = await boot();
  const n = h.calls.length;
  h.els['filter-date'].value = '2026-11-03';
  h.dispatch(h.els['filter-date'], 'input');
  assert.equal(h.calls.length, n);
  done(h);
});

test('show all: clears the filter and fetches exactly once without events', async () => {
  const h = await boot();
  const spy = [];
  h.els['filter-date'].addEventListener('change', () => spy.push('change'));
  h.els['filter-date'].addEventListener('input', () => spy.push('input'));
  h.els['filter-date'].value = '2026-11-03';
  const n = h.calls.length;
  const result = h.dispatch(h.els['show-all'], 'click');
  assert.equal(result.listenerCount, 1);
  assert.equal(h.els['filter-date'].value, '');
  assert.equal(h.calls.length, n + 1);
  assert.equal(lastCall(h).url, '/api/bookings');
  await flush();
  assert.equal(h.calls.length, n + 1);
  assert.deepEqual(spy, []);
  done(h);
});

test('booking: submit prevents default, disables Book, posts raw values', async () => {
  const h = await boot();
  const v = fill(h, { title: '  Pad  ', start: '9:00' });
  const n = h.calls.length;
  const result = submit(h);
  assert.equal(result.prevented, true);
  assert.equal(h.els.book.disabled, true);
  assert.equal(h.calls.length, n + 1);
  const call = lastCall(h);
  assert.equal(call.url, '/api/bookings');
  assert.equal(call.options.method, 'POST');
  assert.equal(JSON.stringify(call.options.headers), '{"Content-Type":"application/json"}');
  assert.equal(JSON.stringify(Object.keys(call.options).sort()), '["body","headers","method"]');
  assert.equal(JSON.stringify(JSON.parse(call.options.body)), JSON.stringify({ ...v, start: '9:00' }));
  assert.equal(Object.keys(JSON.parse(call.options.body)).length, 5);
  done(h);
});

test('booking: submit while Book is disabled sends nothing but still prevents default', async () => {
  const h = await boot();
  fill(h);
  submit(h);
  const n = h.calls.length;
  const again = submit(h);
  assert.equal(again.prevented, true);
  assert.equal(h.calls.length, n);
  assert.equal(h.els.book.disabled, true);
  done(h);
});

test('booking: 201 re-enables Book, empties title only and error, refetches list', async () => {
  const h = await boot();
  const v = fill(h);
  h.els.error.textContent = 'old';
  submit(h);
  const post = lastCall(h).index;
  h.respond(post, reply(201, booking(5)));
  await flush();
  assert.equal(h.els.book.disabled, false);
  assert.equal(h.els.title.value, '');
  for (const id of ['room', 'date', 'start', 'end']) assert.equal(h.els[id].value, v[id], id);
  assert.equal(h.els.error.textContent, '');
