  const n = h.calls.length;
  h.dispatch(button, 'click');
  return { h, button, n };
}

test('cancel: click disables the button and sends DELETE for its id', async () => {
  const { h, button, n } = await withCancelButton();
  assert.equal(button.disabled, true);
  assert.equal(h.calls.length, n + 1);
  assert.equal(lastCall(h).url, '/api/bookings/7');
  assert.equal(lastCall(h).options.method, 'DELETE');
  h.dispatch(button, 'click');
  assert.equal(h.calls.length, n + 1);
  done(h);
});

test('cancel: 204 is accepted without reading the body, then the list is fetched', async () => {
  const { h, button, n } = await withCancelButton();
  const spec = reply(204, null, { badJson: true });
  h.respond(n, spec);
  await flush();
  assert.equal(spec.jsonCalls, 0);
  assert.equal(h.els.error.textContent, '');
  assert.equal(button.disabled, false);
  assert.equal(h.calls.length, n + 2);
  assert.equal(lastCall(h).url, '/api/bookings');
  assert.equal(method(lastCall(h)), 'GET');
  done(h);
});

test('cancel: error statuses show the message and still refetch the list', async () => {
  const cases = [
    [404, { error: 'booking not found' }, 'booking not found'],
    [200, { weird: true }, FAILED],
    [500, null, FAILED],
  ];
  for (const [status, body, message] of cases) {
    const { h, button, n } = await withCancelButton();
    h.respond(n, reply(status, body));
    await flush();
    assert.equal(h.els.error.textContent, message, String(status));
    assert.equal(button.disabled, false);
    assert.equal(h.calls.length, n + 2);
    assert.equal(lastCall(h).url, '/api/bookings');
    done(h);
  }
});

test('cancel: no reply shows the network message, enables the button, no refetch', async () => {
  const rejected = await withCancelButton();
  rejected.h.fail(rejected.n);
  await flush();
  const unreadable = await withCancelButton();
  unreadable.h.respond(unreadable.n, reply(500, null, { badJson: true }));
  await flush();
  for (const { h, button, n } of [rejected, unreadable]) {
    assert.equal(h.els.error.textContent, NO_REPLY);
    assert.equal(button.disabled, false);
    assert.equal(h.calls.length, n + 1);
    done(h);
  }
});

